<script setup lang="ts">
import {computed,getCurrentInstance,ref} from 'vue'
import FeaturePage from '../../components/FeaturePage.vue'
import {clearAvatar,saveAvatar,useAvatar} from '../../profile/avatar'
import {readImageDataUrl} from '../../profile/avatarFiles'
import {confirmFeature,finishFeatureEdit,useFeatureAction,useFeatureTask} from '../../features/useFeatureTask'
const {avatar}=useAvatar();const preview=ref('');const source=ref('');const sourceBytes=ref(0);const width=ref(0);const height=ref(0);const zoom=ref(1);const x=ref(50);const y=ref(50);const original=ref('');const instance=getCurrentInstance()
const {busy,actionError,perform}=useFeatureAction();const {loading,error,reload}=useFeatureTask(async()=>{preview.value=avatar.value;original.value=preview.value},{refreshOnShow:false,beforeBack:confirmDiscard,backUrl:'/pages/personal-profile/index'})
const isDirty=computed(()=>Boolean(source.value)||preview.value!==original.value)
function confirmDiscard():Promise<boolean>{if(busy.value)return Promise.resolve(false);return isDirty.value?confirmFeature('放弃头像修改？','未保存的裁剪结果不会替换原头像。','放弃修改'):Promise.resolve(true)}
function pickImage():Promise<UniNamespace.ChooseImageSuccessCallbackResult>{return new Promise((resolve,reject)=>uni.chooseImage({count:1,sourceType:['album'],sizeType:['original'],success:resolve,fail:()=>reject(new Error('没有选择图片，原头像保留'))}))}
async function crop():Promise<string>{
  const size=Math.min(width.value,height.value)/zoom.value;const left=(width.value-size)*x.value/100;const top=(height.value-size)*y.value/100
  const context=uni.createCanvasContext('avatar-crop',instance?.proxy)
  context.drawImage(source.value,left,top,size,size,0,0,192,192)
  return new Promise((resolve,reject)=>context.draw(false,()=>uni.canvasToTempFilePath({canvasId:'avatar-crop',x:0,y:0,width:192,height:192,destWidth:192,destHeight:192,fileType:'png',quality:1,success:result=>{void readImageDataUrl(result.tempFilePath).then(resolve,reject)},fail:()=>reject(new Error('头像裁剪失败，请重新选择'))},instance?.proxy)))
}
function handleChoose():void{void perform(async()=>{const selected=await pickImage();const path=selected.tempFilePaths[0];if(!path)throw new Error('未选择图片');const files:unknown=selected.tempFiles;const first=Array.isArray(files)?files[0] as Record<string,unknown>|undefined:undefined;const fileSize=typeof first?.size==='number'?first.size:await new Promise<number>((resolve,reject)=>uni.getFileInfo({filePath:path,success:result=>resolve(result.size),fail:()=>reject(new Error('无法读取图片大小'))}));if(fileSize>2*1024*1024)throw new Error('源图片不能超过 2MB');const image=await new Promise<UniNamespace.GetImageInfoSuccessData>((resolve,reject)=>uni.getImageInfo({src:path,success:resolve,fail:()=>reject(new Error('图片格式不可用，请选择 PNG 或 JPEG'))}));source.value=path;sourceBytes.value=fileSize;width.value=image.width;height.value=image.height;zoom.value=1;x.value=50;y.value=50;preview.value=await crop()})}
function handlePreview():void{void perform(async()=>{if(source.value)preview.value=await crop()})}
function handleSave():void{void perform(async()=>{if(source.value)preview.value=await crop();if(!preview.value)throw new Error('请先选择图片');await saveAvatar({dataUrl:preview.value,sourceBytes:sourceBytes.value});original.value=preview.value;source.value='';await finishFeatureEdit('/pages/personal-profile/index')})}
function handleReset():void{void perform(async()=>{if(!await confirmFeature('恢复默认头像？','只移除头像图片，个人资料和学习记录保留。','恢复默认'))return;await clearAvatar();preview.value='';original.value='';source.value='';await finishFeatureEdit('/pages/personal-profile/index')})}
function sliderValue(event:unknown):number{const raw=event as{detail?:{value?:number}};return Number(raw.detail?.value)||0}
</script>
<template><FeaturePage title="头像裁剪" back-url="/pages/personal-profile/index" :loading="loading" :error="error" :before-back="confirmDiscard" @retry="reload"><div class="avatar-preview"><image v-if="preview" :src="preview" mode="aspectFill" role="img" aria-label="裁剪后的头像"/><span v-else>学</span></div><p class="feature-note">选择不超过 2MB 的图片，裁剪为 192×192 小图。保存时移除原图位置等元数据，小图随本机数据备份。</p><button role="button" class="feature-button secondary" :disabled="busy" @click="handleChoose">选择头像图片</button><template v-if="source"><label class="feature-field"><span>放大 {{ zoom.toFixed(1) }} 倍</span><slider :value="zoom*10" :min="10" :max="30" :step="1" aria-label="头像放大倍数" @change="zoom=sliderValue($event)/10"/></label><label class="feature-field"><span>水平位置 {{ x }}%</span><slider :value="x" :min="0" :max="100" aria-label="头像水平位置" @change="x=sliderValue($event)"/></label><label class="feature-field"><span>垂直位置 {{ y }}%</span><slider :value="y" :min="0" :max="100" aria-label="头像垂直位置" @change="y=sliderValue($event)"/></label><button role="button" class="feature-link" :disabled="busy" @click="handlePreview">更新裁剪预览</button></template><button v-if="avatar" role="button" class="feature-link" :disabled="busy" @click="handleReset">恢复默认头像</button><p v-if="actionError" class="feature-error" role="alert">{{ actionError }}</p><template #footer><button role="button" class="feature-button" :disabled="busy||!preview" @click="handleSave">保存头像</button></template></FeaturePage><canvas canvas-id="avatar-crop" id="avatar-crop" class="avatar-processing-canvas"/></template>
<style scoped>.avatar-preview { display:grid;place-items:center;width:168px;height:168px;margin:8px auto 24px;border-radius:50%;overflow:hidden;background:var(--color-primary-soft);color:var(--color-primary);font-size:64px; }.avatar-preview image { width:100%;height:100%; }.avatar-processing-canvas { position:fixed;left:-1000px;top:0;width:192px;height:192px;pointer-events:none; }</style>
